package com.nyayaconnect.document;
import com.nyayaconnect.auth.SpringAccess;import com.nyayaconnect.casemgmt.CaseAccessService;import com.nyayaconnect.common.Api;import com.nyayaconnect.security.AuthenticationFilter;import com.nyayaconnect.security.SessionUser;import jakarta.servlet.http.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class DocumentDownloadServlet extends HttpServlet {
 private CaseAccessService access; private DocumentDao dao; private DocumentIntegrityService integrity;
 public void init(){access=SpringAccess.bean(getServletContext(),CaseAccessService.class);dao=SpringAccess.bean(getServletContext(),DocumentDao.class);integrity=SpringAccess.bean(getServletContext(),DocumentIntegrityService.class);}
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{try{SessionUser u=(SessionUser)req.getSession(false).getAttribute(AuthenticationFilter.SESSION_KEY);String[] p=req.getPathInfo().split("/");if(p.length<2)throw new IllegalArgumentException("Document id is required.");UUID id=UUID.fromString(p[1]);DocumentDao.DocumentRecord d=dao.find(id).orElseThrow(()->new FileNotFoundException("Document not found."));access.requireAccess(u,d.caseId());Path file=integrity.safePath(d.storageKey());if(!Files.isRegularFile(file))throw new FileNotFoundException("Document content is unavailable.");res.setContentType(d.mimeType());res.setHeader("Content-Disposition","attachment; filename=\""+d.originalName().replace("\"","_")+"\"");res.setContentLengthLong(Files.size(file));Files.copy(file,res.getOutputStream());dao.accessLog(id,u.id(),"DOWNLOAD",req.getRemoteAddr());}catch(SecurityException e){Api.error(res,403,"FORBIDDEN",e.getMessage());}catch(FileNotFoundException|NoSuchFileException e){Api.error(res,404,"DOCUMENT_NOT_FOUND",e.getMessage());}catch(Exception e){Api.error(res,500,"DOWNLOAD_FAILED","Document download failed safely.");}}
}
